"""Append measured payload/time costs to completed independent companion audit."""
import json
from pathlib import Path
BASE=Path(__file__).resolve().parents[1]
paths=sorted((BASE/'audit').glob('reasoning-companion-independent-*.json'))
if not paths:raise RuntimeError('Independent companion audit not complete')
path=paths[-1];audit=json.loads(path.read_text());producer=json.loads((BASE/'integration/reasoning-companion/results/metrics.json').read_text());assert audit['status']=='PASS_WITH_SCOPE_LIMITS'
rows=[]
for seed in [17,43,91]:
    for split in ['iid','depth8']:
        a=next(g for g in audit['groups'] if g['seed']==seed and g['split']==split and g['condition']=='uncompacted');b=next(g for g in audit['groups'] if g['seed']==seed and g['split']==split and g['condition']=='window4')
        rows.append(dict(seed=seed,split=split,uncompacted_mean_episode_seconds=a['cost_mean']['seconds'],window4_mean_episode_seconds=b['cost_mean']['seconds'],window4_time_ratio=b['cost_mean']['seconds']/a['cost_mean']['seconds'],uncompacted_mean_peak_serialized_bytes=a['cost_mean']['reasoning_peak_active_serialized_bytes'],window4_mean_peak_serialized_bytes=b['cost_mean']['reasoning_peak_active_serialized_bytes'],uncompacted_max_peak_serialized_bytes=a['cost_max']['reasoning_peak_active_serialized_bytes'],window4_max_peak_serialized_bytes=b['cost_max']['reasoning_peak_active_serialized_bytes'],uncompacted_max_active_traces=a['cost_max']['reasoning_max_resident_traces'],window4_max_active_traces=b['cost_max']['reasoning_max_resident_traces'],window4_total_compactions=round(b['cost_mean']['reasoning_compactions']*128),window4_total_rereads=round(b['cost_mean']['reasoning_rereads']*128),window4_same_heading_continuations=round(b['cost_mean']['same_heading_reasoning_continuations']*128)))
summary=dict(independent_audit=str(path),producer_total_wall_seconds=producer['seconds'],auditor_wall_seconds=audit['seconds'],rows=rows,total_same_heading_continuations=sum(r['window4_same_heading_continuations'] for r in rows),total_reasoning_compactions=sum(r['window4_total_compactions'] for r in rows),total_rereads=sum(r['window4_total_rereads'] for r in rows),scope='Measured run_text_episode seconds under actual local workload and serialized historical trace payload bytes; no process RAM or isolated throughput claim')
output=BASE/'audit/reasoning-companion-cost-addendum.json'
with output.open('x') as f:json.dump(summary,f,indent=2)
lines=['','## Actual payload and timing costs','',f"Producer wall time: {producer['seconds']:.2f}s. Independent read-only audit wall time: {audit['seconds']:.2f}s. These are different operations and are not summed into model inference cost.",'', '| Seed | Split | Uncompacted episode seconds | Window4 episode seconds | Window4 / uncompacted | Mean peak serialized bytes: uncompacted | Mean peak serialized bytes: window4 |','|---|---|---:|---:|---:|---:|---:|']
for r in rows:lines.append(f"| {r['seed']} | {r['split']} | {r['uncompacted_mean_episode_seconds']:.6f} | {r['window4_mean_episode_seconds']:.6f} | {r['window4_time_ratio']:.3f} | {r['uncompacted_mean_peak_serialized_bytes']:.1f} | {r['window4_mean_peak_serialized_bytes']:.1f} |")
lines+=['',f"Window4 totals: {summary['total_reasoning_compactions']} full generated-history compactions and {summary['total_rereads']} rereads. Same-heading continuation counter: {summary['total_same_heading_continuations']}. This counter counts a later compact boundary under an already encountered queried heading within the same episode, including replay of earlier queries; it is not a count of new semantic discoveries or independent solved problems.",'','Serialized payload size counts retained generated trace JSON only. Model weights, current title state, graph, encoder/global-memory/KV caches and other working objects remain resident outside this buffer. The observed4-versus8 history bound is therefore not a total RAM reduction measurement. Episode timings include actual parsing/archive work and local contention; the added exact boundary persistence/restore checks have real overhead.','',f'Cost details: `{output}`.']
with (BASE/'reports/reasoning-window-independent-audit.md').open('a') as f:f.write('\n'.join(lines)+'\n')
print(json.dumps(summary,indent=2))
